package com.shikshasetu.controller;
import com.shikshasetu.model.*;import com.shikshasetu.portal.*;import com.shikshasetu.repo.*;import com.shikshasetu.service.*;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;import org.springframework.http.*;import org.springframework.web.server.ResponseStatusException;import java.time.LocalDateTime;import java.util.*;
@RestController @RequestMapping("/api/chat") public class ChatController{
 private final PortalUserRepository users;private final ChatInteractionRepository chats;private final EmpatheticChatService assistant;private final PortalAuditService audit;private final ChatEngagementAnalyticsService engagementAnalytics;
 @Value("${shikshasetu.privacy.chat-retention-days:90}") private int retentionDays;
 public ChatController(PortalUserRepository u,ChatInteractionRepository c,EmpatheticChatService a,PortalAuditService audit,ChatEngagementAnalyticsService engagementAnalytics){users=u;chats=c;assistant=a;this.audit=audit;this.engagementAnalytics=engagementAnalytics;}
 public record ChatRequest(@NotBlank @Size(max=5000) String message){}
 @PostMapping("/interactions") @Transactional public Map<String,Object> send(@Valid @RequestBody ChatRequest r){PortalUser u=PortalAuthContext.require().user();if(!"STUDENT".equals(u.getRole())||u.getStudentId()==null)throw new ResponseStatusException(HttpStatus.FORBIDDEN,"The learning companion is available to approved student accounts only");if(u.getInstitutionId()==null)throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Institution workspace required");if(!u.isChatMonitoringConsent())throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Chat usage monitoring consent is required to use the institutional companion");EmpatheticChatService.Result result=assistant.respond(r.message().trim());ChatInteraction saved=chats.save(new ChatInteraction(u.getInstitutionId(),u.getId(),u.getStudentId(),result.topic(),result.sentiment(),r.message().trim(),result.reply(),LocalDateTime.now().plusDays(Math.max(7,Math.min(365,retentionDays)))));audit.record("CHAT_INTERACTION",saved.getId(),"Chat topic="+result.topic()+", tone="+result.sentiment());return Map.of("interactionId",saved.getId(),"topic",result.topic(),"sentiment",result.sentiment(),"reply",result.reply(),"createdAt",saved.getCreatedAt(),"retentionDays",Math.max(7,Math.min(365,retentionDays)));}
 @GetMapping("/my-analytics") public Map<String,Object> myAnalytics(){PortalUser u=PortalAuthContext.require().user();if(!"STUDENT".equals(u.getRole())||u.getStudentId()==null)throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Student record required");LocalDateTime since=LocalDateTime.now().minusDays(30);List<ChatInteraction> rows=chats.findTop500ByStudentIdAndExpiresAtAfterOrderByCreatedAtDesc(u.getStudentId(),LocalDateTime.now()).stream().filter(x->Objects.equals(x.getInstitutionId(),u.getInstitutionId())&&!x.getCreatedAt().isBefore(since)).toList();Map<String,Long> topics=rows.stream().collect(java.util.stream.Collectors.groupingBy(ChatInteraction::getTopic,java.util.TreeMap::new,java.util.stream.Collectors.counting()));int activeDays=(int)rows.stream().map(x->x.getCreatedAt().toLocalDate()).distinct().count();var engagement=engagementAnalytics.analyseStudent(u.getInstitutionId(),u.getStudentId(),30).orElse(null);return Map.of("periodDays",30,"interactionCount",rows.size(),"activeDays",activeDays,"distinctTopics",topics.size(),"topics",topics,"activityBand",engagement==null?"INSUFFICIENT_COHORT_DATA":engagement.activityBand(),"notice","This is a descriptive learning-companion usage summary. Activity bands are not academic scores or wellbeing diagnoses.");}
 @GetMapping("/my-interactions") public List<Map<String,Object>> mine(){PortalUser u=PortalAuthContext.require().user();if(!"STUDENT".equals(u.getRole())||u.getStudentId()==null)throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Student record required");return chats.findTop500ByStudentIdAndExpiresAtAfterOrderByCreatedAtDesc(u.getStudentId(),LocalDateTime.now()).stream().filter(x->Objects.equals(x.getInstitutionId(),u.getInstitutionId())).map(x->Map.<String,Object>of("id",x.getId(),"topic",x.getTopic(),"sentiment",x.getSentiment(),"message",x.getUserMessage(),"reply",x.getAssistantReply(),"createdAt",x.getCreatedAt())).toList();}
}
